  item_data.kind                         offset=AbsoluteStatic(0x08) size=Fixed(4) align=Aligned(8) repr=ValueConverted atomic=AtomicWord
  item_data.locale                       offset=AbsoluteStatic(0x0C) size=Fixed(4) align=Aligned(4) repr=ValueConverted atomic=AtomicWord
  item_data.value                        offset=AbsoluteStatic(0x10) size=Bounded(0, 4294967279) align=Aligned(8) repr=MemoryIdentical atomic=AtomicWord mutate=Shifting

struct item_pair size=6 repr=ValueConverted
  item_pair.reserved                     offset=AbsoluteStatic(0x00) size=Fixed(2) align=Aligned(8) repr=ValueConverted atomic=AtomicWord
  item_pair.number                       offset=AbsoluteStatic(0x02) size=Fixed(2) align=Aligned(2) repr=ValueConverted atomic=AtomicWord
  item_pair.total                        offset=AbsoluteStatic(0x04) size=Fixed(2) align=Aligned(4) repr=ValueConverted atomic=AtomicWord

